struct VirtualOutputStrings {
    let title: String
    let caption: String
    let install: String
    let update: String
    let updateTitle: String
    let updateBody: String
    private let details: Details
    var installTitle: String { details.installTitle }
    var installBody: String { details.installBody }
    var remove: String { details.remove }
    var removeTitle: String { details.removeTitle }
    var removeBody: String { details.removeBody }
    var privacyTitle: String { details.privacyTitle }
    var privacyBody: String { details.privacyBody }
    func message(_ issue: VirtualOutputSupport.Issue) -> String {
        switch issue {
        case .outputUnavailable, .setupFailed: return details.failed
        case .privacyUnverified: return details.privacyFailed
        case .inUse: return details.inUse
        case .stopped: return details.stopped
        case .installerMissing: return details.installerMissing
        case .removalFailed: return details.removalFailed
        }
    }
    private init(language: AppLanguage, title: String, caption: String, install: String) {
        self.title = title; self.caption = caption; self.install = install
        (self.update, self.updateTitle, self.updateBody) = Self.updateText(language)
        self.details = Self.extra(language)
    }
    static func localized(_ language: AppLanguage) -> Self {
        switch language {
        case .enUS: return .init(language: language, title: "Software volume fallback", caption: "Uses hardware volume when available. Otherwise enables system volume with per-app controls.", install: "Install audio driver")
        case .ptBR: return .init(language: language, title: "Volume por software", caption: "Usa o volume nativo quando disponível. Caso contrário, o Vorssaint Audio controla o volume do sistema e mantém os controles por app.", install: "Instalar componente de volume")
        case .tr: return .init(language: language, title: "Yazılım ses yedeği", caption: "Varsa aygıtın yerel ses kontrolünü kullanır. Aksi halde Vorssaint Audio, uygulama kaydırıcılarını koruyarak sistem sesini kontrol eder.", install: "Sistem ses bileşenini yükle")
        case .ru: return .init(language: language, title: "Программная громкость", caption: "Использует встроенную регулировку устройства. Если её нет, Vorssaint Audio управляет системной громкостью, сохраняя регуляторы приложений.", install: "Установить компонент громкости")
        case .es: return .init(language: language, title: "Volumen por software", caption: "Usa el volumen nativo del dispositivo cuando está disponible. Si no, Vorssaint Audio controla el volumen del sistema y conserva los controles por app.", install: "Instalar componente de volumen")
        case .sk: return .init(language: language, title: "Softvérová náhrada hlasitosti", caption: "Prednostne používa natívnu hlasitosť zariadenia. Inak Vorssaint Audio ovláda systémovú hlasitosť a zachová posuvníky jednotlivých aplikácií.", install: "Nainštalovať komponent hlasitosti")
        case .de: return .init(language: language, title: "Software-Lautstärke", caption: "Nutzt verfügbare Lautstärkeregler des Geräts. Andernfalls steuert Vorssaint Audio die Systemlautstärke und behält die App-Regler bei.", install: "Lautstärkekomponente installieren")
        case .fr: return .init(language: language, title: "Volume logiciel de secours", caption: "Utilise le volume natif de l’appareil si disponible. Sinon, Vorssaint Audio contrôle le volume système tout en gardant les curseurs par app.", install: "Installer le composant de volume")
        case .it: return .init(language: language, title: "Volume software alternativo", caption: "Usa il volume nativo del dispositivo se disponibile. Altrimenti Vorssaint Audio controlla il volume di sistema mantenendo i cursori per app.", install: "Installa il componente volume")
        case .ja: return .init(language: language, title: "ソフトウェア音量補助", caption: "利用可能な場合はデバイス標準の音量調整を使用します。それ以外は Vorssaint Audio がアプリ別スライダーを維持してシステム音量を調整します。", install: "音量コンポーネントをインストール")
        case .ko: return .init(language: language, title: "소프트웨어 음량 대체", caption: "지원되는 기기에서는 기본 음량 조절을 사용합니다. 그 외에는 Vorssaint Audio가 앱별 슬라이더를 유지하며 시스템 음량을 조절합니다.", install: "음량 구성요소 설치")
        case .uk: return .init(language: language, title: "Програмна гучність", caption: "Використовує штатне регулювання пристрою, якщо воно доступне. Інакше Vorssaint Audio керує системною гучністю, зберігаючи повзунки програм.", install: "Встановити компонент гучності")
        case .zhHans: return .init(language: language, title: "软件音量回退", caption: "优先使用设备原生音量控制。若不可用，Vorssaint Audio 会控制系统音量，同时保留各个 App 的音量滑块。", install: "安装系统音量组件")
        case .zhTW: return .init(language: language, title: "軟體音量備援", caption: "優先使用裝置原生音量控制。若無法使用，Vorssaint Audio 會控制系統音量，同時保留各個 App 的音量滑桿。", install: "安裝系統音量元件")
        case .zhHK: return .init(language: language, title: "軟件音量備援", caption: "優先使用裝置原生音量控制。若無法使用，Vorssaint Audio 會控制系統音量，同時保留各個 App 的音量滑桿。", install: "安裝系統音量組件")
        }
    }

    private static func updateText(_ language: AppLanguage) -> (String, String, String) {
        switch language {
        case .enUS: return ("Update audio driver", "Update the audio driver?", "Software volume fallback needs a newer Vorssaint Audio driver. Updating requires administrator approval and briefly restarts audio.")
        case .ptBR: return ("Atualizar driver de áudio", "Atualizar o driver de áudio?", "O volume por software precisa de um driver Vorssaint Audio mais recente. A atualização exige aprovação de administrador e reinicia o áudio brevemente.")
        case .tr: return ("Ses sürücüsünü güncelle", "Ses sürücüsü güncellensin mi?", "Yazılım ses yedeği için daha yeni bir Vorssaint Audio sürücüsü gerekiyor. Güncelleme yönetici onayı ister ve sesi kısa süreli yeniden başlatır.")
        case .ru: return ("Обновить аудиодрайвер", "Обновить аудиодрайвер?", "Для программной громкости нужен более новый драйвер Vorssaint Audio. Обновление требует подтверждения администратора и ненадолго перезапускает звук.")
        case .es: return ("Actualizar controlador de audio", "¿Actualizar el controlador de audio?", "El volumen por software necesita un controlador Vorssaint Audio más reciente. La actualización requiere autorización de administrador y reinicia brevemente el audio.")
        case .sk: return ("Aktualizovať zvukový ovládač", "Aktualizovať zvukový ovládač?", "Softvérová náhrada hlasitosti vyžaduje novší ovládač Vorssaint Audio. Aktualizácia vyžaduje schválenie správcu a na chvíľu reštartuje zvuk.")
        case .de: return ("Audiotreiber aktualisieren", "Audiotreiber aktualisieren?", "Die Software-Lautstärke benötigt einen neueren Vorssaint-Audio-Treiber. Das Update erfordert Administratorrechte und startet die Audioausgabe kurz neu.")
        case .fr: return ("Mettre à jour le pilote audio", "Mettre à jour le pilote audio ?", "Le volume logiciel de secours nécessite un pilote Vorssaint Audio plus récent. La mise à jour demande une autorisation administrateur et redémarre brièvement l’audio.")
        case .it: return ("Aggiorna driver audio", "Aggiornare il driver audio?", "Il volume software alternativo richiede un driver Vorssaint Audio più recente. L’aggiornamento richiede l’approvazione di un amministratore e riavvia brevemente l’audio.")
        case .ja: return ("オーディオドライバを更新", "オーディオドライバを更新しますか？", "ソフトウェア音量補助には新しい Vorssaint Audio ドライバが必要です。更新には管理者の承認が必要で、オーディオが一時的に再起動します。")
        case .ko: return ("오디오 드라이버 업데이트", "오디오 드라이버를 업데이트할까요?", "소프트웨어 음량 대체 기능에는 더 최신 Vorssaint Audio 드라이버가 필요합니다. 업데이트하려면 관리자 승인이 필요하며 오디오가 잠시 재시작됩니다.")
        case .uk: return ("Оновити аудіодрайвер", "Оновити аудіодрайвер?", "Для програмної гучності потрібен новіший драйвер Vorssaint Audio. Оновлення потребує підтвердження адміністратора й ненадовго перезапускає звук.")
        case .zhHans: return ("更新音频驱动程序", "更新音频驱动程序？", "软件音量回退需要更新版本的 Vorssaint Audio 驱动程序。更新需要管理员批准，并会短暂重启音频。")
        case .zhTW: return ("更新音訊驅動程式", "更新音訊驅動程式？", "軟體音量備援需要較新版本的 Vorssaint Audio 驅動程式。更新需要管理員批准，並會短暫重新啟動音訊。")
        case .zhHK: return ("更新音訊驅動程式", "更新音訊驅動程式？", "軟件音量備援需要較新版本的 Vorssaint Audio 驅動程式。更新需要管理員批准，並會短暫重新啟動音訊。")
        }
    }

    private struct Details {
        let installTitle: String
        let installBody: String
        let failed: String
        let privacyFailed: String
        let inUse: String
        let stopped: String
        let installerMissing: String
        let remove: String
        let removeTitle: String
        let removeBody: String
        let removalFailed: String
        let privacyTitle: String
        let privacyBody: String
    }
    private static func extra(_ language: AppLanguage) -> Details {
        switch language {
        case .enUS: return .init(installTitle: "Install the audio driver?", installBody: "Software volume fallback requires the optional Vorssaint Audio driver. Installation needs administrator approval and briefly restarts audio. Per-app controls remain available.", failed: "Could not start software volume. Check the selected output and audio permissions, then try again.", privacyFailed: "Safe audio playback could not be verified. Processing was not started.", inUse: "Software volume is already in use by another instance.", stopped: "Audio processing stopped. The physical output was restored.", installerMissing: "The driver installer is unavailable. Reinstall this build of Vorssaint.", remove: "Remove audio driver", removeTitle: "Remove the audio driver?", removeBody: "Software volume fallback will be turned off and the physical output restored. Administrator approval is required to remove Vorssaint Audio and its installer receipt. Audio briefly restarts. Per-app controls remain available.", removalFailed: "The driver was not removed. You can retry or use the bundled uninstall script.", privacyTitle: "Audio privacy", privacyBody: "Playback is processed in memory through an output-only driver. This feature does not read physical microphone streams, save or upload audio. Per-app controls may require System Audio Recording permission. The recorder and selected AirPlay routes are separate features.")
        case .ptBR: return .init(installTitle: "Instalar o driver de áudio?", installBody: "O volume por software requer o driver opcional Vorssaint Audio. A instalação exige aprovação de administrador e reinicia o áudio brevemente. Os controles por app continuam disponíveis.", failed: "Não foi possível iniciar o volume por software. Verifique a saída e as permissões de áudio e tente novamente.", privacyFailed: "Não foi possível verificar a reprodução segura de áudio. O processamento não foi iniciado.", inUse: "Outra instância já está usando o volume por software.", stopped: "O processamento de áudio parou. A saída física foi restaurada.", installerMissing: "O instalador do driver não está disponível. Reinstale esta versão do Vorssaint.", remove: "Remover driver de áudio", removeTitle: "Remover o driver de áudio?", removeBody: "O volume por software será desativado e a saída física restaurada. A remoção do Vorssaint Audio e do registro de instalação exige aprovação de administrador. O áudio reinicia brevemente. Os controles por app continuam disponíveis.", removalFailed: "O driver não foi removido. Tente novamente ou use o script de remoção incluído.", privacyTitle: "Privacidade do áudio", privacyBody: "A reprodução é processada na memória por um driver somente de saída. Este recurso não lê microfones físicos, salva ou envia áudio. Os controles por aplicativo podem exigir permissão para gravar o áudio do sistema. O gravador e as rotas AirPlay selecionadas são recursos separados.")
        case .tr: return .init(installTitle: "Ses sürücüsü yüklensin mi?", installBody: "Yazılım ses yedeği, isteğe bağlı Vorssaint Audio sürücüsünü gerektirir. Yükleme yönetici onayı ister ve sesi kısa süreli yeniden başlatır. Uygulama ses kontrolleri kullanılabilir kalır.", failed: "Yazılım ses düzeyi başlatılamadı. Çıkışı ve ses izinlerini kontrol edip yeniden deneyin.", privacyFailed: "Güvenli ses çalma doğrulanamadı. İşleme başlatılmadı.", inUse: "Yazılım ses düzeyi başka bir uygulama örneği tarafından kullanılıyor.", stopped: "Ses işleme durdu. Fiziksel çıkış geri yüklendi.", installerMissing: "Sürücü yükleyicisi kullanılamıyor. Bu Vorssaint derlemesini yeniden yükleyin.", remove: "Ses sürücüsünü kaldır", removeTitle: "Ses sürücüsü kaldırılsın mı?", removeBody: "Yazılım ses yedeği kapatılır ve fiziksel çıkış geri yüklenir. Vorssaint Audio ve yükleme kaydını kaldırmak yönetici onayı gerektirir. Ses kısa süreli yeniden başlatılır. Uygulama ses kontrolleri kullanılabilir kalır.", removalFailed: "Sürücü kaldırılmadı. Yeniden deneyin veya birlikte verilen kaldırma betiğini kullanın.", privacyTitle: "Ses gizliliği", privacyBody: "Çalma sesi yalnızca çıkış sağlayan bir sürücüyle bellekte işlenir. Bu özellik fiziksel mikrofon akışlarını okumaz, ses kaydetmez veya yüklemez. Uygulama ses denetimleri sistem sesini kaydetme izni gerektirebilir. Kaydedici ve seçilen AirPlay yolları ayrı özelliklerdir.")
        case .ru: return .init(installTitle: "Установить аудиодрайвер?", installBody: "Для программной громкости нужен дополнительный драйвер Vorssaint Audio. Установка требует подтверждения администратора и ненадолго перезапускает звук. Регуляторы приложений остаются доступны.", failed: "Не удалось запустить программную громкость. Проверьте выход и разрешения на аудио и повторите попытку.", privacyFailed: "Не удалось проверить безопасность воспроизведения. Обработка не запущена.", inUse: "Программная громкость уже используется другим экземпляром приложения.", stopped: "Обработка звука остановлена. Физический выход восстановлен.", installerMissing: "Установщик драйвера недоступен. Переустановите эту сборку Vorssaint.", remove: "Удалить аудиодрайвер", removeTitle: "Удалить аудиодрайвер?", removeBody: "Программная громкость будет отключена, физический выход восстановлен. Для удаления Vorssaint Audio и записи установщика нужно подтверждение администратора. Звук ненадолго перезапустится. Регуляторы приложений останутся доступны.", removalFailed: "Драйвер не удалён. Повторите попытку или используйте прилагаемый скрипт удаления.", privacyTitle: "Конфиденциальность звука", privacyBody: "Воспроизведение обрабатывается в памяти через драйвер только с выходом. Эта функция не читает физические микрофоны, не сохраняет и не отправляет звук. Управление громкостью приложений может требовать разрешения на запись системного звука. Рекордер и выбранные маршруты AirPlay — отдельные функции.")
        case .es: return .init(installTitle: "¿Instalar el controlador de audio?", installBody: "El volumen por software requiere el controlador opcional Vorssaint Audio. La instalación necesita autorización de administrador y reinicia brevemente el audio. Los controles por app siguen disponibles.", failed: "No se pudo iniciar el volumen por software. Comprueba la salida y los permisos de audio e inténtalo de nuevo.", privacyFailed: "No se pudo verificar la reproducción segura de audio. No se inició el procesamiento.", inUse: "Otra instancia ya está usando el volumen por software.", stopped: "El procesamiento de audio se detuvo. Se restauró la salida física.", installerMissing: "El instalador del controlador no está disponible. Reinstala esta versión de Vorssaint.", remove: "Eliminar controlador de audio", removeTitle: "¿Eliminar el controlador de audio?", removeBody: "Se desactivará el volumen por software y se restaurará la salida física. Eliminar Vorssaint Audio y el registro de instalación requiere autorización de administrador. El audio se reiniciará brevemente. Los controles por app seguirán disponibles.", removalFailed: "No se eliminó el controlador. Vuelve a intentarlo o utiliza el script de desinstalación incluido.", privacyTitle: "Privacidad del audio", privacyBody: "La reproducción se procesa en memoria mediante un controlador solo de salida. Esta función no lee micrófonos físicos ni guarda o sube audio. Los controles por aplicación pueden requerir permiso para grabar el audio del sistema. La grabadora y las rutas AirPlay seleccionadas son funciones independientes.")
        case .sk: return .init(installTitle: "Nainštalovať zvukový ovládač?", installBody: "Softvérová hlasitosť vyžaduje voliteľný ovládač Vorssaint Audio. Inštalácia potrebuje potvrdenie správcu a krátko reštartuje zvuk. Ovládanie jednotlivých aplikácií zostane dostupné.", failed: "Softvérovú hlasitosť sa nepodarilo spustiť. Skontrolujte výstup a zvukové oprávnenia a skúste to znova.", privacyFailed: "Nepodarilo sa overiť bezpečné prehrávanie zvuku. Spracovanie sa nespustilo.", inUse: "Softvérovú hlasitosť už používa iná inštancia aplikácie.", stopped: "Spracovanie zvuku sa zastavilo. Fyzický výstup bol obnovený.", installerMissing: "Inštalátor ovládača nie je dostupný. Preinštalujte túto zostavu Vorssaint.", remove: "Odstrániť zvukový ovládač", removeTitle: "Odstrániť zvukový ovládač?", removeBody: "Softvérová náhrada hlasitosti sa vypne a obnoví sa fyzický výstup. Odstránenie Vorssaint Audio a inštalačného záznamu vyžaduje súhlas správcu. Zvuk sa krátko reštartuje. Ovládanie aplikácií zostane dostupné.", removalFailed: "Ovládač nebol odstránený. Skúste to znova alebo použite priložený odinštalačný skript.", privacyTitle: "Súkromie zvuku", privacyBody: "Prehrávanie sa spracúva v pamäti cez ovládač iba s výstupom. Táto funkcia nečíta fyzické mikrofóny, neukladá ani neodosiela zvuk. Ovládanie hlasitosti aplikácií môže vyžadovať povolenie na nahrávanie systémového zvuku. Nahrávač a zvolené trasy AirPlay sú samostatné funkcie.")
        case .de: return .init(installTitle: "Audiotreiber installieren?", installBody: "Software-Lautstärke benötigt den optionalen Treiber Vorssaint Audio. Die Installation erfordert eine Administratorfreigabe und startet Audio kurz neu. Die App-Regler bleiben verfügbar.", failed: "Software-Lautstärke konnte nicht gestartet werden. Prüfe Ausgabe und Audioberechtigungen und versuche es erneut.", privacyFailed: "Die sichere Audiowiedergabe konnte nicht bestätigt werden. Die Verarbeitung wurde nicht gestartet.", inUse: "Software-Lautstärke wird bereits von einer anderen Instanz verwendet.", stopped: "Die Audioverarbeitung wurde beendet. Die physische Ausgabe wurde wiederhergestellt.", installerMissing: "Das Treiberinstallationsprogramm ist nicht verfügbar. Installiere diese Vorssaint-Version erneut.", remove: "Audiotreiber entfernen", removeTitle: "Audiotreiber entfernen?", removeBody: "Die Software-Lautstärke wird deaktiviert und der physische Ausgang wiederhergestellt. Das Entfernen von Vorssaint Audio und des Installationsbelegs erfordert Administratorrechte. Audio startet kurz neu. Die App-Regler bleiben verfügbar.", removalFailed: "Der Treiber wurde nicht entfernt. Versuche es erneut oder nutze das mitgelieferte Deinstallationsskript.", privacyTitle: "Audio-Datenschutz", privacyBody: "Die Wiedergabe wird über einen reinen Ausgabetreiber im Arbeitsspeicher verarbeitet. Diese Funktion liest keine physischen Mikrofone und speichert oder überträgt kein Audio. App-Lautstärkeregler können die Berechtigung zur Aufnahme von Systemaudio benötigen. Recorder und ausgewählte AirPlay-Routen sind separate Funktionen.")
        case .fr: return .init(installTitle: "Installer le pilote audio ?", installBody: "Le volume logiciel nécessite le pilote facultatif Vorssaint Audio. Son installation demande une autorisation administrateur et redémarre brièvement l’audio. Les réglages par app restent disponibles.", failed: "Impossible de démarrer le volume logiciel. Vérifiez la sortie et les autorisations audio, puis réessayez.", privacyFailed: "La sécurité de la lecture audio n’a pas pu être vérifiée. Le traitement n’a pas démarré.", inUse: "Le volume logiciel est déjà utilisé par une autre instance.", stopped: "Le traitement audio s’est arrêté. La sortie physique a été rétablie.", installerMissing: "Le programme d’installation du pilote est indisponible. Réinstallez cette version de Vorssaint.", remove: "Supprimer le pilote audio", removeTitle: "Supprimer le pilote audio ?", removeBody: "Le volume logiciel sera désactivé et la sortie physique rétablie. Supprimer Vorssaint Audio et le reçu d’installation demande une autorisation administrateur. L’audio redémarre brièvement. Les réglages par app restent disponibles.", removalFailed: "Le pilote n’a pas été supprimé. Réessayez ou utilisez le script de désinstallation fourni.", privacyTitle: "Confidentialité audio", privacyBody: "La lecture est traitée en mémoire par un pilote de sortie uniquement. Cette fonction ne lit aucun microphone physique et ne sauvegarde ni ne transmet de son. Les réglages par application peuvent nécessiter l’autorisation d’enregistrer l’audio système. L’enregistreur et les sorties AirPlay sélectionnées sont des fonctions distinctes.")
        case .it: return .init(installTitle: "Installare il driver audio?", installBody: "Il volume software richiede il driver opzionale Vorssaint Audio. L’installazione richiede l’approvazione di un amministratore e riavvia brevemente l’audio. I controlli per app restano disponibili.", failed: "Impossibile avviare il volume software. Controlla l’uscita e i permessi audio, poi riprova.", privacyFailed: "Impossibile verificare la sicurezza della riproduzione audio. L’elaborazione non è stata avviata.", inUse: "Il volume software è già usato da un’altra istanza.", stopped: "L’elaborazione audio si è interrotta. L’uscita fisica è stata ripristinata.", installerMissing: "Il programma di installazione del driver non è disponibile. Reinstalla questa versione di Vorssaint.", remove: "Rimuovi driver audio", removeTitle: "Rimuovere il driver audio?", removeBody: "Il volume software verrà disattivato e l’uscita fisica ripristinata. La rimozione di Vorssaint Audio e della ricevuta di installazione richiede l’approvazione di un amministratore. L’audio si riavvia brevemente. I controlli per app restano disponibili.", removalFailed: "Il driver non è stato rimosso. Riprova o usa lo script di disinstallazione incluso.", privacyTitle: "Privacy audio", privacyBody: "La riproduzione viene elaborata in memoria tramite un driver di sola uscita. Questa funzione non legge microfoni fisici, non salva né carica audio. I controlli per app possono richiedere il permesso di registrare l’audio di sistema. Il registratore e i percorsi AirPlay selezionati sono funzioni separate.")
        case .ja: return .init(installTitle: "オーディオドライバをインストールしますか？", installBody: "ソフトウェア音量には、オプションの Vorssaint Audio ドライバが必要です。インストールには管理者の承認が必要で、オーディオが一時的に再起動します。アプリ別の音量調整は引き続き利用できます。", failed: "ソフトウェア音量を開始できませんでした。出力先とオーディオのアクセス権を確認して再試行してください。", privacyFailed: "安全な音声再生を確認できなかったため、処理を開始しませんでした。", inUse: "ソフトウェア音量は別のインスタンスで使用中です。", stopped: "オーディオ処理が停止し、物理出力が復元されました。", installerMissing: "ドライバのインストーラが見つかりません。この Vorssaint ビルドを再インストールしてください。", remove: "オーディオドライバを削除", removeTitle: "オーディオドライバを削除しますか？", removeBody: "ソフトウェア音量を無効にして、物理出力に戻します。Vorssaint Audio とインストール記録の削除には管理者の承認が必要です。オーディオが一時的に再起動します。アプリ別の音量調整は引き続き利用できます。", removalFailed: "ドライバは削除されませんでした。再試行するか、同梱のアンインストールスクリプトを使用してください。", privacyTitle: "オーディオのプライバシー", privacyBody: "再生音声は出力専用ドライバを介してメモリ内で処理されます。この機能は物理マイクを読み取らず、音声の保存やアップロードも行いません。アプリ別の音量調整にはシステムオーディオの収録許可が必要な場合があります。録画機能と選択したAirPlay経路は別の機能です。")
        case .ko: return .init(installTitle: "오디오 드라이버를 설치할까요?", installBody: "소프트웨어 음량에는 선택 사항인 Vorssaint Audio 드라이버가 필요합니다. 설치하려면 관리자 승인이 필요하며 오디오가 잠시 다시 시작됩니다. 앱별 음량 조절은 계속 사용할 수 있습니다.", failed: "소프트웨어 음량을 시작할 수 없습니다. 출력 기기와 오디오 권한을 확인한 후 다시 시도하세요.", privacyFailed: "안전한 오디오 재생을 확인할 수 없어 처리를 시작하지 않았습니다.", inUse: "다른 인스턴스에서 소프트웨어 음량을 사용 중입니다.", stopped: "오디오 처리가 중단되어 실제 출력 기기로 복원되었습니다.", installerMissing: "드라이버 설치 프로그램을 사용할 수 없습니다. 이 Vorssaint 빌드를 다시 설치하세요.", remove: "오디오 드라이버 제거", removeTitle: "오디오 드라이버를 제거할까요?", removeBody: "소프트웨어 음량이 꺼지고 실제 출력 기기로 복원됩니다. Vorssaint Audio와 설치 기록을 제거하려면 관리자 승인이 필요합니다. 오디오가 잠시 다시 시작됩니다. 앱별 음량 조절은 계속 사용할 수 있습니다.", removalFailed: "드라이버가 제거되지 않았습니다. 다시 시도하거나 포함된 제거 스크립트를 사용하세요.", privacyTitle: "오디오 개인정보 보호", privacyBody: "재생 오디오는 출력 전용 드라이버를 통해 메모리에서 처리됩니다. 이 기능은 실제 마이크를 읽거나 오디오를 저장 또는 업로드하지 않습니다. 앱별 음량 조절에는 시스템 오디오 녹음 권한이 필요할 수 있습니다. 녹화 기능과 선택한 AirPlay 경로는 별도 기능입니다.")
        case .uk: return .init(installTitle: "Установити аудіодрайвер?", installBody: "Програмна гучність потребує додаткового драйвера Vorssaint Audio. Установлення вимагає підтвердження адміністратора та ненадовго перезапускає звук. Регулятори програм залишаються доступними.", failed: "Не вдалося запустити програмну гучність. Перевірте вихід і дозволи на аудіо та повторіть спробу.", privacyFailed: "Не вдалося перевірити безпечність відтворення звуку. Обробку не запущено.", inUse: "Програмну гучність уже використовує інший екземпляр програми.", stopped: "Обробку звуку зупинено. Фізичний вихід відновлено.", installerMissing: "Інсталятор драйвера недоступний. Перевстановіть цю збірку Vorssaint.", remove: "Видалити аудіодрайвер", removeTitle: "Видалити аудіодрайвер?", removeBody: "Програмну гучність буде вимкнено, фізичний вихід відновлено. Для видалення Vorssaint Audio та запису інсталятора потрібне підтвердження адміністратора. Звук ненадовго перезапуститься. Регулятори програм залишаться доступними.", removalFailed: "Драйвер не видалено. Спробуйте ще раз або скористайтеся доданим скриптом видалення.", privacyTitle: "Конфіденційність звуку", privacyBody: "Відтворення обробляється в пам’яті через драйвер лише з виходом. Ця функція не читає фізичні мікрофони, не зберігає та не надсилає звук. Керування гучністю програм може потребувати дозволу на запис системного звуку. Записувач і вибрані маршрути AirPlay є окремими функціями.")
        case .zhHans: return .init(installTitle: "安装音频驱动程序？", installBody: "软件音量回退需要可选的 Vorssaint Audio 驱动程序。安装需要管理员批准，并会短暂重启音频。各个 App 的音量控制仍可使用。", failed: "无法启动软件音量。请检查所选输出和音频权限，然后重试。", privacyFailed: "无法验证音频播放的安全性，因此未启动处理。", inUse: "另一个实例正在使用软件音量。", stopped: "音频处理已停止，已恢复物理输出。", installerMissing: "驱动程序安装器不可用。请重新安装此 Vorssaint 版本。", remove: "移除音频驱动程序", removeTitle: "移除音频驱动程序？", removeBody: "将关闭软件音量回退并恢复物理输出。移除 Vorssaint Audio 及其安装记录需要管理员批准。音频会短暂重启。各个 App 的音量控制仍可使用。", removalFailed: "未移除驱动程序。请重试或使用随附的卸载脚本。", privacyTitle: "音频隐私", privacyBody: "播放音频通过仅输出的驱动程序在内存中处理。此功能不读取物理麦克风，不保存或上传音频。各个 App 的音量控制可能需要系统音频录制权限。录制功能和所选 AirPlay 路由是独立功能。")
        case .zhTW: return .init(installTitle: "安裝音訊驅動程式？", installBody: "軟體音量備援需要選用的 Vorssaint Audio 驅動程式。安裝需要管理員核准，並會短暫重新啟動音訊。各個 App 的音量控制仍可使用。", failed: "無法啟動軟體音量。請檢查所選輸出與音訊權限，然後再試一次。", privacyFailed: "無法確認音訊播放的安全性，因此未啟動處理。", inUse: "另一個執行個體正在使用軟體音量。", stopped: "音訊處理已停止，已還原實體輸出。", installerMissing: "驅動程式安裝程式無法使用。請重新安裝此 Vorssaint 版本。", remove: "移除音訊驅動程式", removeTitle: "移除音訊驅動程式？", removeBody: "將關閉軟體音量備援並還原實體輸出。移除 Vorssaint Audio 及其安裝記錄需要管理員核准。音訊會短暫重新啟動。各個 App 的音量控制仍可使用。", removalFailed: "未移除驅動程式。請再試一次或使用隨附的解除安裝指令稿。", privacyTitle: "音訊隱私權", privacyBody: "播放音訊透過僅輸出的驅動程式在記憶體中處理。此功能不讀取實體麥克風，不儲存或上傳音訊。各個 App 的音量控制可能需要系統音訊錄製權限。錄製功能與所選 AirPlay 路由是獨立功能。")
        case .zhHK: return .init(installTitle: "安裝音訊驅動程式？", installBody: "軟件音量備援需要選用的 Vorssaint Audio 驅動程式。安裝需要管理員批准，並會短暫重新啟動音訊。各個 App 的音量控制仍可使用。", failed: "無法啟動軟件音量。請檢查所選輸出及音訊權限，然後再試一次。", privacyFailed: "無法確認音訊播放的安全性，因此未啟動處理。", inUse: "另一個執行個體正在使用軟件音量。", stopped: "音訊處理已停止，已還原實體輸出。", installerMissing: "驅動程式安裝程式無法使用。請重新安裝此 Vorssaint 版本。", remove: "移除音訊驅動程式", removeTitle: "移除音訊驅動程式？", removeBody: "將關閉軟件音量備援並還原實體輸出。移除 Vorssaint Audio 及其安裝記錄需要管理員批准。音訊會短暫重新啟動。各個 App 的音量控制仍可使用。", removalFailed: "未移除驅動程式。請重試或使用隨附的解除安裝指令稿。", privacyTitle: "音訊私隱", privacyBody: "播放音訊透過僅輸出的驅動程式在記憶體中處理。此功能不讀取實體咪高峰，不儲存或上載音訊。各個 App 的音量控制可能需要系統音訊錄製權限。錄製功能與所選 AirPlay 路由是獨立功能。")
        }
    }
